extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var box := await instantiate_scene("res://ui/dialogue_box.tscn")
	if not check("box_loaded", box != null, "La scena dialogue_box.tscn deve caricarsi correttamente"):
		return

	var dialogue_label := find_by_name(box, "DialogueLabel") as RichTextLabel
	var indicator := find_by_name(box, "ContinueIndicator") as Label
	if not check("nodes", dialogue_label != null and indicator != null, "DialogueLabel e ContinueIndicator devono esistere"):
		return

	box.characters_per_second = 20.0
	box.show_line("Guida", "Questa è una frase sufficientemente lunga per testare l'interruzione con il tasto di avanzamento.")
	await wait_frames(2)

	var is_typing_method = has_function(box, "is_typing")
	check("has_is_typing", is_typing_method, "Lo script deve avere la funzione is_typing()")
	if is_typing_method:
		var typing_val = call_if_exists(box, "is_typing")
		check("is_typing_true", typing_val == true, "Mentre il testo sta comparendo is_typing() deve restituire true")

	await wait_seconds(0.3)
	check("typing_midway", dialogue_label.visible_ratio < 0.9, "Dopo pochi decimi di secondo il testo non deve essere ancora finito")

	var event := InputEventAction.new()
	event.action = "advance_dialogue"
	event.pressed = true
	box._unhandled_input(event)
	await wait_frames(2)

	check("skip_ratio", dialogue_label.visible_ratio >= 1.0, "Premendo advance_dialogue il testo deve diventare subito interamente visibile (visible_ratio = 1.0)")
	check("skip_indicator", indicator.visible, "Premendo advance_dialogue l'indicatore deve comparire")

	if is_typing_method:
		var typing_after = call_if_exists(box, "is_typing")
		check("is_typing_false", typing_after == false, "Dopo aver completato la battuta is_typing() deve restituire false")

